select b.member_id as memberId, m.member_no as memberNo, m.nickname as nickname, b.remain_points as remainPoints, b.expire_time as expireTime from biz_point_batch b join biz_member m on m.member_id = b.member_id where b.status = 1 and b.remain_points > 0 and b.expire_time >= #{now} and b.expire_time <= #{cutoff}
and b.member_id = #{memberId}
order by b.expire_time asc, b.batch_id asc
